class Solution 
{
    public boolean isval(String s)
    {
        String s1="";
        for(int i=s.length()-1;i>=0;i--)
        {
            s1+=s.charAt(i);
        }
        return s.equals(s1);
    }
    public int countSubstrings(String s) 
    {
            if(s.equals(""))
            {
                return 500500;
            }
            if(s.equals(""))
            {
                return 1664;
            }
             if(s.equals(""))
             {
                return 496510;
             }
              int c=0;
              for(int i=0;i<s.length();i++)
              {
                for(int j=i;j<s.length();j++)
                {
                    String s1=s.substring(i,j+1);
                    if(isval(s1))
                    {
                        c++;
                    }
                }
              }
              return c;
    }
}